<script>
const type=document.querySelector('#type'),party=document.querySelector('#party-field'),other=document.querySelector('#other-account'),receipt=document.querySelector('#receipt-field'),kind=document.querySelector('#receipt-kind'),dueField=document.querySelector('#due-field'),due=document.querySelector('#due'),paymentKindField=document.querySelector('#payment-kind-field'),paymentKind=document.querySelector('#payment-kind'),billField=document.querySelector('#bill-field'),bill=document.querySelector('#bill'),method=document.querySelector('#method-field'),accountLabel=document.querySelector('#account-label'),partyLabel=document.querySelector('#party-label'),otherLabel=document.querySelector('#other-label');
function sync(){let v=type.value,cash=['money_received','money_paid'].includes(v),internal=['transfer','journal'].includes(v);party.hidden=internal;other.hidden=!internal;other.querySelector('select').disabled=!internal;method.hidden=!cash;receipt.hidden=v!=='money_received';paymentKindField.hidden=v!=='money_paid';dueField.hidden=!(v==='money_received'&&kind.value==='customer_payment');due.disabled=dueField.hidden;billField.hidden=!(v==='money_paid'&&paymentKind.value==='supplier_bill');bill.disabled=billField.hidden;accountLabel.textContent=v==='transfer'?'From account':v==='journal'?'Debit account':'Farm account';partyLabel.textContent=v==='money_paid'?'Paid to':'Received from';otherLabel.textContent=v==='journal'?'Credit account':'To account';} type.onchange=sync;kind.onchange=sync;paymentKind.onchange=sync;sync();
</script>
